import json
try:
    b = config.get('body') if isinstance(config, dict) else None
    if isinstance(b, dict):
        t = str(b.get('type') or '')
        vars['create_attempted'] = t
        fields = b.get('fields')
        if isinstance(fields, str):
            try:
                fields = json.loads(fields)
            except Exception:
                fields = dict()
        if not isinstance(fields, dict):
            fields = dict()
        store = vars.get('req_store')
        try:
            store = json.loads(store) if isinstance(store, str) else (store if isinstance(store, dict) else dict())
        except Exception:
            store = dict()
        spec = store.get(t)
        if isinstance(spec, list):
            clean = dict()
            for f in spec:
                if not isinstance(f, dict): continue
                n = f.get('name')
                if n not in fields: continue
                v = fields.get(n)
                if v is None or str(v).strip() == '': continue
                fmt = f.get('format')
                if fmt == 'amount':
                    s = re.sub(r'[^0-9.]', '', str(v))
                    try:
                        x = float(s)
                        v = int(x) if x == int(x) else round(x, 2)
                    except Exception:
                        v = str(v)
                elif fmt in ('digits', 'postcode'):
                    v = re.sub(r'\D', '', str(v))
                elif fmt == 'date':
                    v = norm_date(v)
                elif fmt == 'choice':
                    opts = [str(o) for o in (f.get('options') or [])]
                    low = str(v).strip().lower()
                    for o in opts:
                        if o.lower() == low:
                            v = o
                else:
                    v = str(v).strip()
                clean[n] = v
            fields = clean
        b['fields'] = fields
except Exception:
    pass

